from __future__ import annotations
import base64, bz2, hashlib
from pathlib import Path
TARGET=Path("tui_gateway/hosted_room_driver.py")
EXPECTED_CURRENT="79789fe9e725ba3e2bf15440dc1de0ce60b45bb7d137d3c42b86f58eed1839fe"
EXPECTED_CANDIDATE="fb64b666a67606a68c0df1c463b303ea52c7cc5e1f6d2d4efab69c7f645ab03e"
PAYLOAD=""
current=TARGET.read_bytes()
digest=hashlib.sha256(current).hexdigest()
if digest != EXPECTED_CURRENT: raise SystemExit(f"unexpected runtime source: {digest}")
candidate=bz2.decompress(base64.b64decode(PAYLOAD))
if hashlib.sha256(candidate).hexdigest()!=EXPECTED_CANDIDATE: raise SystemExit("candidate digest mismatch")
TARGET.write_bytes(candidate)
print(f"applied={EXPECTED_CANDIDATE}")